-- Atomically reject a draft reference if photo cleanup claimed the asset first.
CREATE TRIGGER contribution_photos_insert BEFORE INSERT ON contributions WHEN EXISTS(SELECT 1 FROM json_each(NEW.draft_json,'$.photos') p LEFT JOIN assets a ON a.id=json_extract(p.value,'$.id') WHERE a.id IS NULL OR a.state!='ready' OR a.user_id!=NEW.user_id OR a.group_id!=NEW.group_id OR a.issue_id!=NEW.issue_id) BEGIN SELECT RAISE(ABORT,'photo_not_ready'); END;
CREATE TRIGGER contribution_photos_update BEFORE UPDATE OF draft_json ON contributions WHEN EXISTS(SELECT 1 FROM json_each(NEW.draft_json,'$.photos') p LEFT JOIN assets a ON a.id=json_extract(p.value,'$.id') WHERE a.id IS NULL OR a.state!='ready' OR a.user_id!=NEW.user_id OR a.group_id!=NEW.group_id OR a.issue_id!=NEW.issue_id) BEGIN SELECT RAISE(ABORT,'photo_not_ready'); END;
